def link(url,label,cls=''):return f'<a href="{escape(url,quote=True)}" class="{cls}">{label}</a>'
def intro(text,url='',label='',tag=''):
 return '<div class="task-intro"><div>'+('<span class="eyebrow">'+tag+'</span>' if tag else '')+'<p>'+text+'</p></div>'+(link(url,label,'button') if url else '')+'</div>'
def cards(items):
 return '<div class="choice-grid">'+''.join('<a class="choice-card" href="'+url+'"><span class="choice-index" aria-hidden="true">'+str(i+1).zfill(2)+'</span><h2>'+title+'</h2><p>'+desc+'</p><span class="choice-go">'+cta+' <span aria-hidden="true">→</span></span></a>' for i,(title,desc,url,cta) in enumerate(items))+'</div>'
def block(title,items,ordered=False):
 tag='ol' if ordered else 'ul'
 return '<section class="reading-section"><h2>'+title+'</h2><'+tag+'>'+''.join('<li>'+s+'</li>' for s in items)+'</'+tag+'></section>'
def steps(items):
 """A how-to guide as numbered steps: what to do, and a short word on why or how."""
 return '<ol class="guide-steps">'+''.join('<li><h3>'+t+'</h3><p>'+d+'</p></li>' for t,d in items)+'</ol>'
def detail(title,body):return '<details class="guidance-detail"><summary>'+title+'</summary><div>'+body+'</div></details>'
def nextstep(title,text,url,label):return '<aside class="next-step"><div><h2>'+title+'</h2><p>'+text+'</p></div>'+link(url,label,'text-link')+'</aside>'
def missing(label,jira):
 detail={'Logo pack link needs completing':'The logo pack download is still being set up.','Brand Book download needs completing':'The Brand Book download is still being set up.'}.get(label,'This page does not have a download link yet.')
 return '<aside class="availability-note" role="note"><span class="availability-icon" aria-hidden="true"></span><p><strong>Not yet available.</strong> '+detail+'</p></aside>'
